    const db = {
      get(key) { try { return JSON.parse(localStorage.getItem('lc_'+key)); } catch(e) { return null; } },
      set(key,value) { localStorage.setItem('lc_'+key,JSON.stringify(value)); },
      init() { ['services','lawyers','users','cases','documents','messages','notifications','reviews'].forEach(k=>{ if(!this.get(k)) this.set(k,seed[k]); }); if(!this.get('appointments')) this.set('appointments', makeAppointments()); if(!this.get('favorites')) this.set('favorites',[]); }
    };
    function makeAppointments() { const appts=[]; const dates=['Sep 02, 2026','Sep 03, 2026','Sep 04, 2026','Sep 05, 2026','Sep 08, 2026','Sep 09, 2026','Sep 10, 2026','Sep 11, 2026','Sep 12, 2026','Sep 15, 2026']; const status=['Confirmed','Pending','Completed','Cancelled','Confirmed']; for(let i=0;i<30;i++){appts.push({id:'LC-2026-'+(10245+i),lawyerId:(i%20)+1,customer:'Samira Ahmed',service:seed.lawyers[i%20].specialization[0],date:dates[i%dates.length],time:['09:00 AM','10:30 AM','12:00 PM','02:00 PM','03:30 PM'][i%5],type:['Online','Office','Phone'][i%3],status:status[i%5],reason:'Demo consultation request'});} return appts; }
    let activeRoute='home', selectedLawyerId=1, selectedDate=3, selectedSlot='', activeConversation=1, booking={lawyerId:null,type:'Online',date:'September 3, 2026',time:'',reason:'',step:1};
    const getLawyers=()=>db.get('lawyers')||[]; const getServices=()=>db.get('services')||[]; const getUser=()=>window.LC_AUTH||null; const getLawyer=id=>getLawyers().find(l=>l.id===Number(id));
    function esc(text){return String(text||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}
    function formatMoney(n){return 'Rs. '+Number(n).toLocaleString('en-PK');}
    function formatStatus(s){return '<span class="status '+String(s).toLowerCase().replaceAll(' ','-')+'">'+esc(s)+'</span>';}
    function emptyState(icon,title,text,cta,action){return '<div class="empty"><i class="fa-solid '+icon+'"></i><h3>'+title+'</h3><p>'+text+'</p>'+ (cta?'<button class="btn small" onclick="'+action+'">'+cta+'</button>':'')+'</div>';}
    function initApp(){db.init(); const savedTheme=localStorage.getItem('lc_theme');if(savedTheme==='dark')document.body.classList.add('dark'); updateThemeIcon(); populateOptions();renderHome();renderResources();renderNotifications();updateHeader();routeFromHash();}
    function navigate(route,params={}){ activeRoute=route; document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));const view=document.getElementById('view-'+route); if(!view){route='home';document.getElementById('view-home').classList.add('active');}else view.classList.add('active');document.querySelectorAll('.primary-nav a[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===route));document.getElementById('primaryNav').classList.remove('open'); document.querySelectorAll('.notification-menu,.global-search').forEach(e=>e.classList.remove('open'));
      if(route==='lawyers'){if(params.service!==undefined)document.getElementById('filterService').value=params.service;if(params.location!==undefined)document.getElementById('filterLocation').value=params.location;filterLawyers();}
      if(route==='profile')renderProfile(params.id||selectedLawyerId); if(route==='dashboard')renderCustomerDashboard(params.tab||'dashboard');if(route==='lawyer-dashboard')renderLawyerDashboard(params.tab||'dashboard');if(route==='admin-dashboard')renderAdminDashboard(params.tab||'dashboard');if(route==='messages')renderMessages();if(route==='cases')renderCases();if(route==='documents')renderDocuments();if(route==='appointments')renderAppointments();window.scrollTo(0,0); history.replaceState(null,'','#'+route);}
    function routeFromHash(){const route=location.hash.replace('#',''); if(route && document.getElementById('view-'+route))navigate(route);else navigate('home');}
    function scrollHome(id){navigate('home');setTimeout(()=>document.getElementById(id)?.scrollIntoView({behavior:'smooth'}),100);}
    function toggleMobileNav(){document.getElementById('primaryNav').classList.toggle('open');}
    function toggleTheme(){document.body.classList.toggle('dark');localStorage.setItem('lc_theme',document.body.classList.contains('dark')?'dark':'light');updateThemeIcon();}
    function updateThemeIcon(){const i=document.getElementById('themeIcon');if(i)i.className=document.body.classList.contains('dark')?'fa-solid fa-sun':'fa-regular fa-moon';}
    function populateOptions(){const services=getServices(); const lawyers=getLawyers();const cities=[...new Set(lawyers.map(l=>l.location))];const serviceOpts='<option value="">All services</option>'+services.map(s=>'<option value="'+esc(s.name)+'">'+esc(s.name)+'</option>').join('');const locOpts='<option value="">All locations</option>'+cities.map(c=>'<option value="'+esc(c)+'">'+esc(c)+'</option>').join('');document.getElementById('filterService').innerHTML=serviceOpts;document.getElementById('filterLocation').innerHTML=locOpts;document.getElementById('serviceOptions').innerHTML=services.map(s=>'<option value="'+esc(s.name)+'">').join('');document.getElementById('locationOptions').innerHTML=cities.map(c=>'<option value="'+esc(c)+'">').join('');document.getElementById('matchService').innerHTML='<option value="">Legal help needed</option>'+services.map(s=>'<option value="'+esc(s.name)+'">'+esc(s.name)+'</option>').join('');document.getElementById('matchLocation').innerHTML='<option value="">Preferred location</option>'+cities.map(c=>'<option value="'+esc(c)+'">'+esc(c)+'</option>').join('');}
    function renderHome(){const services=getServices();document.getElementById('homeServices').innerHTML=services.map(serviceMarkup).join('');document.getElementById('allServices').innerHTML=services.map(serviceMarkup).join('');document.getElementById('featuredLawyers').innerHTML=getLawyers().filter(l=>l.verified).slice(0,3).map(lawyerCard).join('');const stats=[['fa-users','10,000+','Customers'],['fa-scale-balanced','500+','Lawyers'],['fa-layer-group','50+','Legal Services'],['fa-location-dot','25+','Cities']];document.getElementById('trustCounters').innerHTML=stats.map(s=>'<div class="trust-stat"><i class="fa-solid '+s[0]+' trust-icon"></i><div><strong data-counter="'+s[1]+'">0</strong><span>'+s[2]+'</span></div></div>').join('');setTimeout(animateCounters,100);}
    function animateCounters(){document.querySelectorAll('[data-counter]').forEach(el=>{const target=el.dataset.counter;let n=0;const num=parseInt(target.replace(/\D/g,''),10);const tick=()=>{n+=Math.max(1,Math.ceil(num/28));if(n<num){el.textContent=n.toLocaleString('en-PK')+'+';requestAnimationFrame(tick)}else el.textContent=target;};tick();});}
    function serviceMarkup(s){return '<article class="service" onclick="quickService(\''+esc(s.name).replace(/'/g,"\\'")+ '\')"><i class="fa-solid '+s.icon+' service-icon"></i><h3>'+esc(s.name)+'</h3><p>'+esc(s.description)+'</p><a>Find Lawyers <i class="fa-solid fa-arrow-right"></i></a></article>';}
    function lawyerCard(l){const fav=isFavorite(l.id);return '<article class="lawyer-card"><button class="favorite-card '+(fav?'on':'')+'" onclick="toggleFavorite('+l.id+',this)" aria-label="Favorite '+esc(l.name)+'"><i class="'+(fav?'fa-solid':'fa-regular')+' fa-heart"></i></button><div class="lawyer-card-top"><img class="lawyer-img" src="'+l.image+'" alt="Portrait of '+esc(l.name)+'" loading="lazy"><div><p class="lawyer-name">'+esc(l.name)+(l.verified?'<span class="verify"><i class="fa-solid fa-circle-check"></i> Verified</span>':'')+'</p><p class="lawyer-specialty">'+esc(l.title)+'</p><p class="lawyer-location"><i class="fa-solid fa-location-dot"></i> '+esc(l.location)+', Pakistan</p></div></div><div class="lawyer-meta"><div><b>'+l.experience+' Years</b><span>Experience</span></div><div><b class="rating"><i class="fa-solid fa-star"></i> '+l.rating+'</b><span>'+l.reviews+' Reviews</span></div></div><div class="card-actions"><button class="btn outline small" onclick="viewProfile('+l.id+')">View Profile</button><button class="btn small" onclick="startBooking('+l.id+')">Book</button></div></article>';}
    function heroSearch(e){e.preventDefault();navigate('lawyers',{service:document.getElementById('heroService').value,location:document.getElementById('heroLocation').value});}
    function quickService(service){navigate('lawyers',{service:service});}
    function runMatching(e){e.preventDefault();const service=document.getElementById('matchService').value,location=document.getElementById('matchLocation').value,type=document.getElementById('matchType').value,urgency=document.getElementById('matchUrgency').value,experience=Number(document.getElementById('matchExperience').value||0);let matches=getLawyers().filter(l=>l.specialization.includes(service)&&l.location===location&&l.experience>=experience&&(!type||l.types.includes(type)));if(urgency==='Today')matches=matches.filter(l=>l.available);const out=document.getElementById('matchResults');out.innerHTML='<p class="eyebrow" style="margin-top:35px">Potential matches based on your selected requirements</p>'+ (matches.length?'<div class="match-list">'+matches.slice(0,6).map(l=>'<article class="lawyer-card"><div class="lawyer-card-top"><img class="lawyer-img" src="'+l.image+'" alt="Portrait of '+esc(l.name)+'"><div><p class="lawyer-name">'+esc(l.name)+(l.verified?'<span class="verify"><i class="fa-solid fa-circle-check"></i> Verified</span>':'')+'</p><p class="lawyer-specialty">'+esc(l.title)+'</p><p class="lawyer-location"><i class="fa-solid fa-location-dot"></i> '+esc(l.location)+'</p></div></div><div class="match-why"><div><i class="fa-solid fa-check"></i> Service matches: '+esc(service)+'</div><div><i class="fa-solid fa-check"></i> Location matches: '+esc(location)+'</div><div><i class="fa-solid fa-check"></i> '+(l.available?'Availability matches your selection':'Profile meets your other selected requirements')+'</div></div><div class="card-actions" style="margin-top:14px"><button class="btn outline small" onclick="viewProfile('+l.id+')">View profile</button><button class="btn small" onclick="startBooking('+l.id+')">Book</button></div></article>').join('')+'</div>':emptyState('fa-magnifying-glass','No direct matches found','Try a nearby city, a lower experience preference or a different consultation type.','Browse all lawyers','navigate(\'lawyers\')'));}
    function priceChanged(){document.getElementById('priceValue').textContent=formatMoney(document.getElementById('filterPrice').value);filterLawyers();}
    function clearFilters(){['filterKeyword','filterService','filterLocation','filterExperience','filterRating'].forEach(id=>document.getElementById(id).value='');document.getElementById('filterPrice').value=10000;document.getElementById('filterAvailable').checked=false;document.getElementById('filterVerified').checked=false;document.querySelectorAll('.filter-panel input[type=checkbox]').forEach(c=>c.checked=false);priceChanged();}
    function filterLawyers(){const out=document.getElementById('lawyerResults');if(!out)return;out.innerHTML='<div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div>';setTimeout(()=>{let list=getLawyers(); const kw=document.getElementById('filterKeyword').value.toLowerCase().trim(),serv=document.getElementById('filterService').value,loc=document.getElementById('filterLocation').value,exp=Number(document.getElementById('filterExperience').value||0),rating=Number(document.getElementById('filterRating').value||0),price=Number(document.getElementById('filterPrice').value);const checked=[...document.querySelectorAll('.filter-panel input[type=checkbox]:checked')].map(x=>x.value);const langs=checked.filter(x=>['English','Urdu','Punjabi'].includes(x));const types=checked.filter(x=>['Online','Office','Phone'].includes(x));list=list.filter(l=>(!kw||[l.name,l.title,...l.specialization].join(' ').toLowerCase().includes(kw))&&(!serv||l.specialization.includes(serv))&&(!loc||l.location===loc)&&l.experience>=exp&&l.rating>=rating&&l.fee<=price&&(!document.getElementById('filterAvailable').checked||l.available)&&(!document.getElementById('filterVerified').checked||l.verified)&&(!langs.length||langs.some(x=>l.languages.includes(x)))&&(!types.length||types.some(x=>l.types.includes(x))));const sort=document.getElementById('sortLawyers').value;list.sort((a,b)=>sort==='rating'?b.rating-a.rating:sort==='experience'?b.experience-a.experience:sort==='price'?a.fee-b.fee:sort==='availability'?Number(b.available)-Number(a.available):Number(b.verified)-Number(a.verified)||b.rating-a.rating);document.getElementById('resultsNumber').textContent=list.length+' '+(list.length===1?'lawyer':'lawyers')+' found';out.innerHTML=list.length?list.map(lawyerResult).join(''):emptyState('fa-magnifying-glass','No lawyers found','Try widening your filters or explore another legal service.','Clear filters','clearFilters()');},370);}
    function lawyerResult(l){const fav=isFavorite(l.id);return '<article class="lawyer-result"><img class="result-img" src="'+l.image+'" alt="Portrait of '+esc(l.name)+'" loading="lazy"><div><div class="result-title"><h3>'+esc(l.name)+'</h3>'+(l.verified?'<span class="verify"><i class="fa-solid fa-circle-check"></i> VERIFIED</span>':'')+'</div><p class="result-description">'+esc(l.title)+' <span class="rating"> <i class="fa-solid fa-star"></i> '+l.rating+'</span> <span style="color:var(--muted)">('+l.reviews+' reviews)</span></p><div class="tag-row"><span class="tag"><i class="fa-solid fa-location-dot"></i> '+esc(l.location)+'</span><span class="tag">'+l.experience+' years</span><span class="tag">'+esc(l.languages.join(', '))+'</span></div></div><div class="result-aside"><div><strong class="fee">'+formatMoney(l.fee)+'</strong><span style="color:var(--muted);font-size:11px">consultation</span><div class="next-slot"><i class="fa-regular fa-calendar-check"></i> '+esc(l.next)+'</div></div><div class="result-buttons"><button class="icon-btn '+(fav?'on':'')+'" onclick="toggleFavorite('+l.id+',this)" aria-label="Favorite"><i class="'+(fav?'fa-solid':'fa-regular')+' fa-heart"></i></button><button class="btn outline small" onclick="viewProfile('+l.id+')">Profile</button><button class="btn small" onclick="startBooking('+l.id+')">Book</button></div></div></article>';}
    function viewProfile(id){selectedLawyerId=Number(id);navigate('profile',{id});}
    function renderProfile(id){const l=getLawyer(id);if(!l){navigate('lawyers');return;}const reviews=(db.get('reviews')||[]).filter(r=>r.lawyerId===l.id);document.getElementById('profileContent').innerHTML='<section class="profile-hero"><img class="profile-img" src="'+l.image+'" alt="Portrait of '+esc(l.name)+'"><div><h1>'+esc(l.name)+(l.verified?'<span class="verify"><i class="fa-solid fa-circle-check"></i> VERIFIED</span>':'')+'</h1><p class="profile-title">'+esc(l.title)+'</p><div class="profile-details"><span><i class="fa-solid fa-location-dot"></i> '+esc(l.location)+', Pakistan</span><span class="rating"><i class="fa-solid fa-star"></i> '+l.rating+' ('+l.reviews+' reviews)</span><span><i class="fa-solid fa-briefcase"></i> '+l.experience+' Years experience</span></div></div><div class="profile-actions"><button class="btn" onclick="startBooking('+l.id+')"><i class="fa-regular fa-calendar-check"></i> Book consultation</button><button class="btn outline" onclick="openMessages('+l.id+')"><i class="fa-regular fa-message"></i> Message</button><button class="btn outline" onclick="toggleFavorite('+l.id+');renderProfile('+l.id+')"><i class="'+(isFavorite(l.id)?'fa-solid':'fa-regular')+' fa-heart"></i> '+(isFavorite(l.id)?'Favorited':'Favorite')+'</button></div></section><div class="profile-content"><div><section class="profile-section"><h2>ABOUT</h2><p>'+esc(l.bio)+' This Legal Connect profile is a frontend demo and does not represent a real legal professional or service.</p></section><section class="profile-section"><h2>SPECIALIZATIONS</h2><div class="specialties">'+l.specialization.map(x=>'<span class="specialty">'+esc(x)+'</span>').join('')+'</div></section><section class="profile-section"><h2>EXPERIENCE & EDUCATION</h2><div class="timeline"><div class="timeline-item"><strong>Independent legal practice</strong><span>'+l.experience+' years of professional experience</span></div><div class="timeline-item"><strong>LL.B. and continuing professional education</strong><span>Professional information presented as demo data</span></div></div></section><section class="profile-section"><h2>LANGUAGES & CONSULTATION OPTIONS</h2><div class="specialties">'+l.languages.map(x=>'<span class="specialty">'+esc(x)+'</span>').join('')+l.types.map(x=>'<span class="specialty"><i class="fa-solid fa-'+(x==='Online'?'video':x==='Phone'?'phone':'building')+'"></i> '+x+'</span>').join('')+'</div></section><section class="profile-section"><h2>CLIENT REVIEWS</h2>'+ (reviews.length?reviews.map(r=>'<div style="padding:13px 0;border-top:1px solid var(--line)"><span class="rating">'+ '<i class="fa-solid fa-star"></i>'.repeat(r.rating)+'</span><p style="margin:5px 0">&quot;'+esc(r.text)+'&quot;</p><span style="font-size:11px;color:var(--muted)">'+esc(r.name)+' | '+esc(r.date)+'</span></div>').join(''):'<p>No reviews yet.</p>')+'<button class="btn outline small" style="margin-top:14px" onclick="addReview('+l.id+')">Leave a demo review</button></section></div><aside class="availability"><h3>Availability</h3><p style="font-size:12px;color:var(--muted);margin:0 0 12px">Select a date to see available times.</p><div id="profileCalendar"></div><p class="slot-label">Available slots</p><div class="slots" id="profileSlots"></div><button id="bookFromProfile" class="btn full" style="margin-top:15px" onclick="startBooking('+l.id+')" disabled>Book selected time</button></aside></div>';renderCalendar('profileCalendar','profileSlots',false);}
    function calendarMarkup(){let html='<div class="calendar-head"><button class="icon-btn" style="width:28px;height:28px" onclick="showToast(\'Calendar set to September 2026 for this demo.\',\'warn\')"><i class="fa-solid fa-chevron-left"></i></button><span class="month-title">September 2026</span><button class="icon-btn" style="width:28px;height:28px" onclick="showToast(\'Calendar set to September 2026 for this demo.\',\'warn\')"><i class="fa-solid fa-chevron-right"></i></button></div><div class="calendar-week">'+['MON','TUE','WED','THU','FRI','SAT','SUN'].map(x=>'<span>'+x+'</span>').join('')+'</div><div class="calendar-days">';for(let i=0;i<2;i++)html+='<button class="calendar-day blank" disabled></button>';for(let d=1;d<=30;d++){let c=[5,12,18,26].includes(d)?'booked':(d===selectedDate?'selected':'available');html+='<button class="calendar-day '+c+'" '+(c==='booked'?'disabled':'')+' onclick="selectDate('+d+')">'+d+'</button>';}html+='</div>';return html;}
    function renderCalendar(calendarId,slotId,inBooking){const cal=document.getElementById(calendarId);if(!cal)return;cal.innerHTML=calendarMarkup();renderSlots(slotId,inBooking);}
    function selectDate(day){selectedDate=day;booking.date='September '+day+', 2026';document.querySelectorAll('#profileCalendar .calendar-day,#bookingCalendar .calendar-day').forEach(x=>x.classList.remove('selected'));document.querySelectorAll('.calendar-day').forEach(b=>{if(b.textContent===String(day)&&!b.disabled)b.classList.add('selected')});renderSlots('profileSlots',false);renderSlots('bookingSlots',true);}
    function renderSlots(id,inBooking){const el=document.getElementById(id);if(!el)return;const times=['09:00 AM','09:30 AM','10:00 AM','10:30 AM','11:00 AM','02:00 PM','02:30 PM'];el.innerHTML=times.map((t,i)=>'<button class="slot '+([1,5].includes(i)?'booked':'')+' '+(selectedSlot===t?'selected':'')+'" '+([1,5].includes(i)?'disabled':'')+' onclick="selectSlot(\''+t+'\','+inBooking+')">'+t+'</button>').join('');}
    function selectSlot(time,inBooking){selectedSlot=time;booking.time=time;renderSlots(inBooking?'bookingSlots':'profileSlots',inBooking);if(!inBooking){document.getElementById('bookFromProfile').disabled=false;}else updateBookingBody();}
    function isFavorite(id){return (db.get('favorites')||[]).includes(Number(id));}
    function toggleFavorite(id,button){const user=getUser();if(!user){showToast('Please sign in to save favorite lawyers.','warn');(window.location.href='/login');return;}let fav=db.get('favorites')||[];if(fav.includes(Number(id))){fav=fav.filter(x=>x!==Number(id));showToast('Removed from your favorites.','warn');}else{fav.push(Number(id));showToast('Lawyer added to your favorites.');}db.set('favorites',fav);if(button){button.classList.toggle('on',fav.includes(Number(id)));const icon=button.querySelector('i');if(icon)icon.className=(fav.includes(Number(id))?'fa-solid':'fa-regular')+' fa-heart';}if(activeRoute==='dashboard')renderCustomerDashboard('favorites');}
    function startBooking(id){const user=getUser();if(!user||user.role!=='customer'){showToast('Sign in with a customer account to book a consultation.','warn');(window.location.href='/login');return;}booking={lawyerId:Number(id),type:'Online',date:'September '+selectedDate+', 2026',time:selectedSlot,reason:'',step:1};openModal('booking');}
    function openModal(kind,data){const layer=document.getElementById('modalLayer'),modal=document.getElementById('modal');modal.className='modal'+(kind==='booking'?' wide':'');layer.classList.add('open');if(kind==='booking'){modal.innerHTML='<div class="modal-head"><h2>Book a consultation</h2><button class="close-modal" onclick="closeModal()">&times;</button></div><div class="modal-body" id="bookingBody"></div><div class="modal-footer" id="bookingFooter"></div>';updateBookingBody();return;}if(kind==='confirm'){modal.innerHTML='<div class="modal-head"><h2>'+esc(data.title)+'</h2><button class="close-modal" onclick="closeModal()">&times;</button></div><div class="modal-body"><p style="color:var(--muted);margin:0">'+esc(data.message)+'</p></div><div class="modal-footer"><button class="btn outline" onclick="closeModal()">Cancel</button><button class="btn '+(data.danger?'danger':'')+'" onclick="closeModal();'+data.action+'">Confirm</button></div>';return;}if(kind==='case'){modal.innerHTML='<div class="modal-head"><h2>Open a case</h2><button class="close-modal" onclick="closeModal()">&times;</button></div><form onsubmit="saveCase(event)"><div class="modal-body"><div class="field"><label>Case title</label><input id="newCaseTitle" required placeholder="Brief title for your matter"></div><div class="field"><label>Legal category</label><select id="newCaseCategory">'+getServices().map(s=>'<option>'+esc(s.name)+'</option>').join('')+'</select></div></div><div class="modal-footer"><button class="btn" type="submit">Create case</button></div></form>';return;}if(kind==='review'){modal.innerHTML='<div class="modal-head"><h2>Leave a demo review</h2><button class="close-modal" onclick="closeModal()">&times;</button></div><form onsubmit="saveReview(event,'+data+')"><div class="modal-body"><div class="field"><label>Rating</label><select id="reviewRating"><option value="5">5 stars</option><option value="4">4 stars</option><option value="3">3 stars</option></select></div><div class="field"><label>Your review</label><textarea id="reviewText" required placeholder="Share your experience"></textarea></div></div><div class="modal-footer"><button class="btn" type="submit">Submit review</button></div></form>';}}
    function closeModal(){document.getElementById('modalLayer').classList.remove('open');}
    function modalBackdrop(e){if(e.target.id==='modalLayer')closeModal();}
    function updateBookingBody(){const l=getLawyer(booking.lawyerId),body=document.getElementById('bookingBody'),footer=document.getElementById('bookingFooter');if(!body||!l)return;let html='<div class="booking-steps">'+[1,2,3,4,5].map(i=>'<span class="booking-step '+(i<=booking.step?'active':'')+'"></span>').join('')+'</div><div class="booking-info"><strong>'+esc(l.name)+'</strong><br>'+esc(l.title)+' | '+formatMoney(l.fee)+' consultation fee</div>';if(booking.step===1)html+='<h3>Select consultation type</h3><p class="subtext" style="font-size:13px">Choose how you would like to meet.</p><div class="booking-option-grid">'+[['Office','fa-building'],['Online','fa-video'],['Phone','fa-phone']].map(x=>'<button class="booking-option '+(booking.type===x[0]?'active':'')+'" onclick="booking.type=\''+x[0]+'\';updateBookingBody()"><i class="fa-solid '+x[1]+'"></i>'+x[0]+'</button>').join('')+'</div>';if(booking.step===2)html+='<h3>Select a date</h3><div class="booking-calendar" id="bookingCalendar"></div>';if(booking.step===3)html+='<h3>Select a time</h3><p class="subtext" style="font-size:13px">Times are shown in Pakistan Standard Time.</p><div class="slots" id="bookingSlots"></div>';if(booking.step===4)html+='<h3>What would you like to discuss?</h3><div class="field" style="margin-top:14px"><label>Consultation reason</label><textarea id="bookingReason" placeholder="Briefly describe your legal matter" required>'+esc(booking.reason)+'</textarea></div>';if(booking.step===5)html+='<h3>Review your request</h3><div class="booking-info" style="line-height:1.8"><strong>Lawyer:</strong> '+esc(l.name)+'<br><strong>Date:</strong> '+esc(booking.date)+'<br><strong>Time:</strong> '+esc(booking.time)+'<br><strong>Type:</strong> '+esc(booking.type)+'<br><strong>Fee:</strong> '+formatMoney(l.fee)+'<br><strong>Reason:</strong> '+esc(booking.reason)+'</div>';body.innerHTML=html;if(booking.step===2)renderCalendar('bookingCalendar','bookingSlots',true);if(booking.step===3)renderSlots('bookingSlots',true);let buttons=booking.step>1?'<button class="btn outline" onclick="booking.step--;updateBookingBody()">Back</button>':'';if(booking.step<5)buttons+='<button class="btn" onclick="nextBookingStep()">Continue <i class="fa-solid fa-arrow-right"></i></button>';else buttons+='<button class="btn gold" id="confirmBooking" onclick="confirmBooking()">Confirm appointment</button>';footer.innerHTML=buttons;}
    function nextBookingStep(){if(booking.step===3&&!booking.time){showToast('Please select a time slot.','warn');return;}if(booking.step===4){const r=document.getElementById('bookingReason').value.trim();if(!r){showToast('Please enter a consultation reason.','warn');return;}booking.reason=r;}booking.step++;updateBookingBody();}
    function confirmBooking(){const btn=document.getElementById('confirmBooking');btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Confirming...';btn.disabled=true;setTimeout(()=>{const appts=db.get('appointments')||[],id='LC-2026-'+(10245+appts.length+1);appts.unshift({id,lawyerId:booking.lawyerId,customer:getUser().name,service:getLawyer(booking.lawyerId).specialization[0],date:booking.date.replace('September','Sep'),time:booking.time,type:booking.type,status:'Pending',reason:booking.reason});db.set('appointments',appts);const notes=db.get('notifications')||[];notes.unshift({id:Date.now(),text:'Your appointment request with '+getLawyer(booking.lawyerId).name+' has been sent.',time:'Just now',read:false});db.set('notifications',notes);renderNotifications();document.getElementById('modal').innerHTML='<div class="modal-body"><div class="success-screen"><div class="success-tick"><i class="fa-solid fa-check"></i></div><h2>Appointment Confirmed</h2><p>Your request has been saved. The lawyer will be able to accept or reschedule it from their dashboard.</p><div class="appointment-id">Appointment ID: '+id+'</div><button class="btn outline small" onclick="showToast(\'Calendar event simulated for this demo.\')"><i class="fa-regular fa-calendar-plus"></i> Add to Calendar</button></div></div><div class="modal-footer"><button class="btn outline" onclick="closeModal();navigate(\'dashboard\')">Back to Dashboard</button><button class="btn" onclick="closeModal();navigate(\'appointments\')">View Appointment</button></div>';showToast('Appointment booked successfully.');},700);}
    function logoutUser(){openModal('confirm',{title:'Sign out?',message:'Are you sure you want to sign out of your Legal Connect demo account?',action:'performLogout()',danger:false});}
    function performLogout(){document.getElementById('realLogoutForm').submit();}
    function updateHeader(){const user=getUser(),login=document.getElementById('loginNav'),reg=document.getElementById('registerNav'),dash=document.getElementById('dashboardNav'),out=document.getElementById('logoutNav');login.classList.toggle('hidden',!!user);reg.classList.toggle('hidden',!!user);dash.classList.toggle('hidden',!user);if(out)out.classList.toggle('hidden',!user);dash.innerHTML=user?'<i class="fa-solid fa-grid-2"></i> '+(user.role==='admin'?'Admin':user.role==='lawyer'?'Practice':'Dashboard'):'';}
    function requireLogin(){if(!getUser()){showToast('Please sign in to access this workspace.','warn');(window.location.href='/login');return false;}return true;}
    function requireCustomer(){const u=getUser();if(!u||u.role!=='customer'){showToast('Please sign in with a customer account.','warn');(window.location.href='/login');return false;}return true;}
    function sideMenu(role,active){const user=getUser()||{name:'Guest'};const customer=[['dashboard','fa-grid-2','Dashboard'],['lawyers','fa-magnifying-glass','Find Lawyers'],['appointments','fa-calendar-check','Appointments'],['messages','fa-message','Messages'],['favorites','fa-heart','Favorites'],['cases','fa-folder-open','Cases'],['documents','fa-file-lines','Documents'],['notifications','fa-bell','Notifications'],['profile-edit','fa-user','Profile'],['settings','fa-gear','Settings']];const lawyer=[['dashboard','fa-grid-2','Dashboard'],['appointments','fa-calendar-check','Appointments'],['availability','fa-calendar-days','Availability'],['clients','fa-users','Clients'],['cases','fa-folder-open','Cases'],['messages','fa-message','Messages'],['services','fa-briefcase','Services'],['reviews','fa-star','Reviews'],['profile-edit','fa-user-pen','Profile'],['settings','fa-gear','Settings']];const admin=[['dashboard','fa-grid-2','Dashboard'],['lawyers','fa-user-tie','Lawyers'],['customers','fa-users','Customers'],['appointments','fa-calendar-check','Appointments'],['services','fa-layer-group','Services'],['locations','fa-location-dot','Locations'],['cases','fa-folder-open','Cases'],['reports','fa-file-chart-column','Reports'],['analytics','fa-chart-line','Analytics'],['content','fa-newspaper','Content'],['notifications','fa-bell','Notifications'],['logs','fa-list-check','Activity Logs'],['settings','fa-gear','Settings']];const list=role==='admin'?admin:role==='lawyer'?lawyer:customer;const title=role==='admin'?'Administrator':role==='lawyer'?'Legal Professional':'Customer account';return '<div class="side-user"><strong>'+esc(user.name)+'</strong><span>'+title+'</span></div>'+list.map(x=>'<a class="'+(active===x[0]?'active':'')+'" onclick="dashboardAction(\''+role+'\',\''+x[0]+'\')"><i class="fa-solid '+x[1]+'"></i>'+x[2]+'</a>').join('')+'<div class="nav-spacer"></div><a onclick="logoutUser()"><i class="fa-solid fa-arrow-right-from-bracket"></i>Logout</a>';}
    function dashboardAction(role,tab){if(tab==='lawyers'&&role==='customer'){navigate('lawyers');return;}if(tab==='messages'){navigate('messages');return;}if(tab==='cases'&&role==='customer'){navigate('cases');return;}if(tab==='documents'&&role==='customer'){navigate('documents');return;}if(tab==='appointments'&&role==='customer'){navigate('appointments');return;}if(tab==='notifications'){toggleNotifications();return;}if(role==='customer')renderCustomerDashboard(tab);else if(role==='lawyer')renderLawyerDashboard(tab);else renderAdminDashboard(tab);}
    function renderCustomerDashboard(tab='dashboard'){if(!requireCustomer())return;document.getElementById('customerSidebar').innerHTML=sideMenu('customer',tab);const main=document.getElementById('customerDashboardMain'),user=getUser(),appts=(db.get('appointments')||[]).filter(a=>a.customer===user.name).slice(0,5);if(tab==='favorites'){const fav=(db.get('favorites')||[]).map(getLawyer).filter(Boolean);main.innerHTML='<div class="dashboard-head"><div><h1>Favorite lawyers</h1><p>Professionals you have saved for later.</p></div><button class="btn" onclick="navigate(\'lawyers\')">Find lawyers</button></div>'+(fav.length?'<div class="lawyers-grid">'+fav.map(lawyerCard).join('')+'</div>':emptyState('fa-heart','No favorite lawyers yet','Save professionals to compare them later.','Find Lawyers','navigate(\'lawyers\')'));return;}if(tab==='profile-edit'||tab==='settings'){main.innerHTML=profileEditor('customer');return;}if(tab!=='dashboard'){main.innerHTML=placeholderDashboard(tab,'customer');return;}const completed=appts.filter(a=>a.status==='Completed').length;main.innerHTML='<div class="dashboard-head"><div><h1>Good morning, '+esc(user.name.split(' ')[0])+'.</h1><p>Here is an overview of your legal services workspace.</p></div><button class="btn" onclick="navigate(\'lawyers\')"><i class="fa-solid fa-magnifying-glass"></i> Find a lawyer</button></div><div class="stats-grid"><div class="stat-box"><i class="fa-regular fa-calendar stat-icon"></i><span>Upcoming appointments</span><strong>'+appts.filter(a=>['Pending','Confirmed'].includes(a.status)).length+'</strong></div><div class="stat-box"><i class="fa-solid fa-circle-check stat-icon"></i><span>Completed appointments</span><strong>'+completed+'</strong></div><div class="stat-box"><i class="fa-regular fa-heart stat-icon"></i><span>Favorite lawyers</span><strong>'+(db.get('favorites')||[]).length+'</strong></div><div class="stat-box"><i class="fa-regular fa-message stat-icon"></i><span>Unread messages</span><strong>2</strong></div></div><div class="dash-grid"><section class="panel"><div class="panel-head"><h3>Upcoming appointments</h3><a class="btn ghost small" onclick="navigate(\'appointments\')">View all</a></div>'+ (appts.length?appts.slice(0,3).map(dashAppointment).join(''):emptyState('fa-calendar','No appointments yet','Start by finding a lawyer.','Find Lawyers','navigate(\'lawyers\')'))+'</section><aside class="panel"><div class="panel-head"><h3>Quick actions</h3></div><div class="quick-actions"><button class="quick-action" onclick="navigate(\'lawyers\')"><i class="fa-solid fa-magnifying-glass"></i>Find the right lawyer</button><button class="quick-action" onclick="navigate(\'messages\')"><i class="fa-regular fa-message"></i>Continue a conversation</button><button class="quick-action" onclick="navigate(\'cases\')"><i class="fa-regular fa-folder-open"></i>Review my cases</button><button class="quick-action" onclick="navigate(\'documents\')"><i class="fa-regular fa-file-lines"></i>Access documents</button></div></aside></div>';}
    function dashAppointment(a){const l=getLawyer(a.lawyerId);return '<div class="appointment-row"><img class="mini-avatar" src="'+(l?.image||'https://i.pravatar.cc/80?img=12')+'" alt=""><div><strong>'+esc(l?.name||'Legal professional')+'</strong><span>'+esc(a.date)+' at '+esc(a.time)+' | '+esc(a.type)+'</span></div>'+formatStatus(a.status)+'</div>';}
    function profileEditor(role){const u=getUser();return '<div class="dashboard-head"><div><h1>'+ (role==='lawyer'?'Professional profile':'Profile & settings')+'</h1><p>Update the local demo information for your account.</p></div></div><form class="panel" onsubmit="saveProfile(event,\''+role+'\')"><div class="two-field"><div class="field"><label>Full name</label><input id="profileName" required value="'+esc(u.name)+'"></div><div class="field"><label>Email</label><input id="profileEmail" type="email" required value="'+esc(u.email)+'"></div></div><div class="two-field"><div class="field"><label>Phone</label><input id="profilePhone" placeholder="+92 300 0000000" value="'+esc(u.phone||'')+'"></div><div class="field"><label>'+ (role==='lawyer'?'Consultation fee (Rs.)':'Preferred location')+'</label><input id="profileExtra" value="'+(role==='lawyer'?(getLawyer(u.lawyerId)?.fee||'3000'):'Karachi')+'"></div></div>'+ (role==='lawyer'?'<div class="field"><label>Professional bio</label><textarea id="profileBio">'+esc(getLawyer(u.lawyerId)?.bio||'')+'</textarea></div>':'')+'<button class="btn" type="submit">Save changes</button></form>';}
    function saveProfile(e,role){e.preventDefault();const u=getUser(),users=db.get('users')||[];const user=users.find(x=>x.id===u.id);user.name=document.getElementById('profileName').value.trim();user.email=document.getElementById('profileEmail').value.trim();user.phone=document.getElementById('profilePhone').value.trim();db.set('users',users);db.set('currentUser',user);if(role==='lawyer'){const lawyers=getLawyers(),l=lawyers.find(x=>x.id===user.lawyerId);if(l){l.fee=Number(document.getElementById('profileExtra').value)||l.fee;l.bio=document.getElementById('profileBio').value.trim()||l.bio;db.set('lawyers',lawyers);}}updateHeader();showToast('Profile updated successfully.');}
    function placeholderDashboard(tab,role){const name=tab.replaceAll('-',' ');const icon=tab==='availability'?'fa-calendar-days':tab==='reviews'?'fa-star':'fa-screwdriver-wrench';return '<div class="dashboard-head"><div><h1>'+name.charAt(0).toUpperCase()+name.slice(1)+'</h1><p>This interactive demo section is ready for future backend data.</p></div></div><div class="panel">'+emptyState(icon,'Manage '+name,'This frontend demo keeps the main marketplace workflows functional.','Return to dashboard',"dashboardAction('"+role+"','dashboard')")+'</div>';}
    function renderLawyerDashboard(tab='dashboard'){const u=getUser();if(!u||u.role!=='lawyer'){showToast('Please sign in with a lawyer account.','warn');(window.location.href='/login');return;}document.getElementById('lawyerSidebar').innerHTML=sideMenu('lawyer',tab);const main=document.getElementById('lawyerDashboardMain'),l=getLawyer(u.lawyerId||1),appointments=(db.get('appointments')||[]).filter(a=>a.lawyerId===l.id);if(tab==='appointments'){main.innerHTML=lawyerAppointments(l,appointments);return;}if(tab==='availability'){main.innerHTML=availabilityManager();return;}if(tab==='profile-edit'){main.innerHTML=profileEditor('lawyer');return;}if(tab!=='dashboard'){main.innerHTML=placeholderDashboard(tab,'lawyer');return;}main.innerHTML='<div class="dashboard-head"><div><h1>Welcome back, '+esc(l.name.replace('Adv. ',''))+'.</h1><p>Here is a live overview of your practice workspace.</p></div><button class="btn" onclick="dashboardAction(\'lawyer\',\'availability\')"><i class="fa-regular fa-calendar-plus"></i> Manage availability</button></div><div class="stats-grid"><div class="stat-box"><i class="fa-regular fa-calendar stat-icon"></i><span>Today\'s appointments</span><strong>'+appointments.filter(a=>a.date.includes('Sep 02')).length+'</strong></div><div class="stat-box"><i class="fa-regular fa-clock stat-icon"></i><span>Pending requests</span><strong>'+appointments.filter(a=>a.status==='Pending').length+'</strong></div><div class="stat-box"><i class="fa-regular fa-folder-open stat-icon"></i><span>Active cases</span><strong>8</strong></div><div class="stat-box"><i class="fa-solid fa-wallet stat-icon"></i><span>Monthly revenue</span><strong>'+formatMoney(128000)+'</strong></div></div><div class="dash-grid"><section class="panel"><div class="panel-head"><h3>Appointment requests</h3><button class="btn ghost small" onclick="dashboardAction(\'lawyer\',\'appointments\')">View all</button></div>'+appointments.slice(0,3).map(a=>'<div class="appointment-row"><img class="mini-avatar" src="https://i.pravatar.cc/80?img=5" alt=""><div><strong>'+esc(a.customer)+'</strong><span>'+esc(a.service)+' | '+esc(a.date)+' at '+esc(a.time)+'</span></div>'+formatStatus(a.status)+'</div>').join('')+'</section><aside class="panel"><div class="panel-head"><h3>Practice tools</h3></div><div class="quick-actions"><button class="quick-action" onclick="dashboardAction(\'lawyer\',\'appointments\')"><i class="fa-regular fa-calendar-check"></i>Review appointment requests</button><button class="quick-action" onclick="dashboardAction(\'lawyer\',\'availability\')"><i class="fa-regular fa-clock"></i>Generate available slots</button><button class="quick-action" onclick="navigate(\'messages\')"><i class="fa-regular fa-message"></i>Open client messages</button></div></aside></div>';}
    function lawyerAppointments(l,appts){return '<div class="dashboard-head"><div><h1>Appointments</h1><p>Accept, reject or reschedule consultation requests.</p></div><button class="btn outline" onclick="dashboardAction(\'lawyer\',\'availability\')">Manage availability</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Service</th><th>Date</th><th>Type</th><th>Status</th><th>Action</th></tr></thead><tbody>'+appts.map(a=>'<tr><td><strong>'+esc(a.customer)+'</strong><span>'+esc(a.time)+'</span></td><td>'+esc(a.service)+'</td><td>'+esc(a.date)+'</td><td>'+esc(a.type)+'</td><td>'+formatStatus(a.status)+'</td><td><div class="row-actions">'+(a.status==='Pending'?'<button class="btn success" onclick="appointmentAction(\''+a.id+'\',\'Confirmed\')">Accept</button><button class="btn danger" onclick="appointmentAction(\''+a.id+'\',\'Rejected\')">Reject</button>':'<button class="btn outline" onclick="showToast(\'Appointment details opened.\')">View</button>')+'<button class="btn outline" onclick="rescheduleAppointment(\''+a.id+'\')">Reschedule</button></div></td></tr>').join('')+'</tbody></table></div>';}
    function appointmentAction(id,status){const a=(db.get('appointments')||[]).find(x=>x.id===id);if(!a)return;a.status=status;db.set('appointments',db.get('appointments'));const n=db.get('notifications')||[];n.unshift({id:Date.now(),text:'Your appointment '+id+' has been '+status.toLowerCase()+'.',time:'Just now',read:false});db.set('notifications',n);renderNotifications();showToast('Appointment '+status.toLowerCase()+'.',status==='Rejected'?'warn':'');renderLawyerDashboard('appointments');}
    function rescheduleAppointment(id){openModal('confirm',{title:'Reschedule appointment?',message:'The demo will move this appointment to the next available date.',action:"doReschedule('"+id+"')",danger:false});}
    function doReschedule(id){const a=(db.get('appointments')||[]).find(x=>x.id===id);if(a){a.date='Sep 16, 2026';a.time='11:00 AM';db.set('appointments',db.get('appointments'));showToast('Appointment rescheduled to Sep 16 at 11:00 AM.');}if(activeRoute==='lawyer-dashboard')renderLawyerDashboard('appointments');else renderAppointments();}
    function availabilityManager(){return '<div class="dashboard-head"><div><h1>Availability</h1><p>Generate appointment slots for your practice.</p></div></div><div class="panel" style="max-width:780px"><div class="two-field"><div class="field"><label>Day</label><select id="slotDay"><option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option></select></div><div class="field"><label>Slot duration</label><select id="slotDuration"><option value="30">30-minute slots</option><option value="60">60-minute slots</option></select></div><div class="field"><label>Start time</label><input id="slotStart" type="time" value="09:00"></div><div class="field"><label>End time</label><input id="slotEnd" type="time" value="17:00"></div></div><button class="btn" onclick="generateSlots()">Generate slots</button><div id="generatedSlots" class="slots" style="margin-top:18px"></div></div>';}
    function generateSlots(){const start=document.getElementById('slotStart').value,end=document.getElementById('slotEnd').value,d=Number(document.getElementById('slotDuration').value);if(!start||!end||start>=end){showToast('Choose a valid start and end time.','error');return;}let [h,m]=start.split(':').map(Number),[eh,em]=end.split(':').map(Number),slots=[];while(h<eh||(h===eh&&m<em)){const hour=((h+11)%12)+1,amp=h>=12?'PM':'AM';slots.push(String(hour).padStart(2,'0')+':'+String(m).padStart(2,'0')+' '+amp);m+=d;if(m>=60){h+=Math.floor(m/60);m%=60;}}document.getElementById('generatedSlots').innerHTML=slots.map(s=>'<button class="slot">'+s+'</button>').join('');showToast(slots.length+' availability slots generated.');}
    function renderAdminDashboard(tab='dashboard'){const u=getUser();if(!u||u.role!=='admin'){showToast('Please sign in with the admin demo account.','warn');(window.location.href='/login');return;}document.getElementById('adminSidebar').innerHTML=sideMenu('admin',tab);const main=document.getElementById('adminDashboardMain');if(tab==='lawyers'){main.innerHTML=adminLawyers();return;}if(tab==='services'){main.innerHTML=adminServices();return;}if(tab==='customers'){main.innerHTML=adminCustomers();return;}if(tab==='analytics'||tab==='reports'){main.innerHTML=adminAnalytics();setTimeout(renderCharts,50);return;}if(tab!=='dashboard'){main.innerHTML=placeholderDashboard(tab,'admin');return;}const lawyers=getLawyers();main.innerHTML='<div class="dashboard-head"><div><h1>Platform overview</h1><p>Monitor the Legal Connect demo marketplace.</p></div><button class="btn" onclick="dashboardAction(\'admin\',\'lawyers\')">Manage lawyers</button></div><div class="stats-grid"><div class="stat-box"><i class="fa-solid fa-user-tie stat-icon"></i><span>Total lawyers</span><strong>'+lawyers.length+'</strong></div><div class="stat-box"><i class="fa-solid fa-circle-check stat-icon"></i><span>Verified lawyers</span><strong>'+lawyers.filter(x=>x.verified).length+'</strong></div><div class="stat-box"><i class="fa-regular fa-hourglass-half stat-icon"></i><span>Pending approvals</span><strong>'+lawyers.filter(x=>x.status==='Pending').length+'</strong></div><div class="stat-box"><i class="fa-solid fa-users stat-icon"></i><span>Total customers</span><strong>10,248</strong></div></div><div class="dash-grid"><section class="panel"><div class="panel-head"><h3>Appointments per month</h3><button class="btn ghost small" onclick="dashboardAction(\'admin\',\'analytics\')">Full analytics</button></div><div class="chart-box"><canvas id="mainChart"></canvas></div></section><aside class="panel"><div class="panel-head"><h3>Admin actions</h3></div><div class="quick-actions"><button class="quick-action" onclick="dashboardAction(\'admin\',\'lawyers\')"><i class="fa-solid fa-user-check"></i>Review lawyer applications</button><button class="quick-action" onclick="dashboardAction(\'admin\',\'services\')"><i class="fa-solid fa-layer-group"></i>Manage legal services</button><button class="quick-action" onclick="dashboardAction(\'admin\',\'customers\')"><i class="fa-solid fa-users"></i>Manage customers</button></div></aside></div>';setTimeout(renderMainChart,20);}
    function adminLawyers(){return '<div class="dashboard-head"><div><h1>Lawyer management</h1><p>Approve, suspend or edit demo lawyer accounts.</p></div><button class="btn" onclick="showToast(\'New lawyer creation would open a full profile form in production.\',\'warn\')"><i class="fa-solid fa-plus"></i> Add lawyer</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Professional</th><th>Specialization</th><th>Location</th><th>Experience</th><th>Status</th><th>Actions</th></tr></thead><tbody>'+getLawyers().map(l=>'<tr><td><div class="table-person"><img src="'+l.image+'" alt=""><div><strong>'+esc(l.name)+'</strong><span>'+esc(l.title)+'</span></div></div></td><td>'+esc(l.specialization.join(', '))+'</td><td>'+esc(l.location)+'</td><td>'+l.experience+' years</td><td>'+formatStatus(l.status)+'</td><td><div class="row-actions"><button class="btn outline" onclick="viewProfile('+l.id+')">View</button>'+(l.status==='Pending'?'<button class="btn success" onclick="adminLawyerAction('+l.id+',\'approve\')">Approve</button><button class="btn danger" onclick="adminLawyerAction('+l.id+',\'reject\')">Reject</button>':'<button class="btn danger" onclick="adminLawyerAction('+l.id+',\'suspend\')">Suspend</button>')+'<button class="btn outline" onclick="adminLawyerAction('+l.id+',\'delete\')">Delete</button></div></td></tr>').join('')+'</tbody></table></div>';}
    function adminLawyerAction(id,action){if(action==='delete'){openModal('confirm',{title:'Delete lawyer?',message:'This will remove the demo lawyer from the directory.',action:'doAdminLawyerAction('+id+',\'delete\')',danger:true});return;}if(action==='reject'){openModal('confirm',{title:'Reject application?',message:'This lawyer will be marked as rejected in the frontend demo.',action:'doAdminLawyerAction('+id+',\'reject\')',danger:true});return;}doAdminLawyerAction(id,action);}
    function doAdminLawyerAction(id,action){let lawyers=getLawyers();const l=lawyers.find(x=>x.id===Number(id));if(!l)return;if(action==='delete'){lawyers=lawyers.filter(x=>x.id!==Number(id));showToast('Lawyer removed from the demo directory.','warn');}else if(action==='approve'){l.status='Verified';l.verified=true;showToast('Lawyer approved and verified.');}else if(action==='reject'){l.status='Rejected';l.verified=false;showToast('Lawyer application rejected.','warn');}else {l.status='Suspended';l.verified=false;showToast('Lawyer account suspended.','warn');}db.set('lawyers',lawyers);populateOptions();renderAdminDashboard('lawyers');}
    function adminCustomers(){const customers=(db.get('users')||[]).filter(u=>u.role==='customer');return '<div class="dashboard-head"><div><h1>Customer management</h1><p>Manage customer accounts in the frontend demo.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Email</th><th>Registration</th><th>Appointments</th><th>Status</th><th>Actions</th></tr></thead><tbody>'+customers.map(c=>'<tr><td><strong>'+esc(c.name)+'</strong></td><td>'+esc(c.email)+'</td><td>Aug 2026</td><td>3</td><td>'+formatStatus(c.suspended?'Suspended':'Active')+'</td><td><div class="row-actions"><button class="btn outline" onclick="showToast(\'Customer profile opened.\')">View</button><button class="btn '+(c.suspended?'success':'danger')+'" onclick="toggleCustomerStatus(\''+c.id+'\')">'+(c.suspended?'Activate':'Suspend')+'</button><button class="btn outline" onclick="deleteCustomer(\''+c.id+'\')">Delete</button></div></td></tr>').join('')+'</tbody></table></div>';}
    function toggleCustomerStatus(id){const users=db.get('users');const u=users.find(x=>x.id===id);u.suspended=!u.suspended;db.set('users',users);showToast('Customer status updated.');renderAdminDashboard('customers');}
    function deleteCustomer(id){openModal('confirm',{title:'Delete customer?',message:'This removes the customer from local demo data.',action:"doDeleteCustomer('"+id+"')",danger:true});}
    function doDeleteCustomer(id){db.set('users',(db.get('users')||[]).filter(x=>x.id!==id));showToast('Customer removed.','warn');renderAdminDashboard('customers');}
    function adminServices(){return '<div class="dashboard-head"><div><h1>Service management</h1><p>Add, edit or remove legal services in the directory.</p></div><button class="btn" onclick="addService()"><i class="fa-solid fa-plus"></i> Add service</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Service</th><th>Description</th><th>Icon</th><th>Status</th><th>Actions</th></tr></thead><tbody>'+getServices().map(s=>'<tr><td><strong>'+esc(s.name)+'</strong></td><td>'+esc(s.description)+'</td><td><i class="fa-solid '+s.icon+'" style="color:var(--gold)"></i></td><td>'+formatStatus('Active')+'</td><td><div class="row-actions"><button class="btn outline" onclick="editService('+s.id+')">Edit</button><button class="btn danger" onclick="removeService('+s.id+')">Delete</button></div></td></tr>').join('')+'</tbody></table></div>';}
    function addService(){const n=prompt('Service name');if(!n||!n.trim())return;const d=prompt('Short description')||'Professional legal support for this matter.';const list=getServices();list.push({id:Date.now(),name:n.trim(),description:d.trim(),icon:'fa-scale-balanced'});db.set('services',list);populateOptions();renderHome();showToast('Service added successfully.');renderAdminDashboard('services');}
    function editService(id){const s=getServices().find(x=>x.id===id);const n=prompt('Service name',s.name);if(!n)return;s.name=n.trim();db.set('services',getServices());populateOptions();renderHome();showToast('Service updated successfully.');renderAdminDashboard('services');}
    function removeService(id){openModal('confirm',{title:'Delete service?',message:'This will remove the service from the demo directory.',action:'doRemoveService('+id+')',danger:true});}
    function doRemoveService(id){db.set('services',getServices().filter(s=>s.id!==id));populateOptions();renderHome();showToast('Service deleted.','warn');renderAdminDashboard('services');}
    function adminAnalytics(){return '<div class="dashboard-head"><div><h1>Analytics & reports</h1><p>Marketplace performance overview based on demo data.</p></div><button class="btn outline" onclick="showToast(\'Demo report exported successfully.\')"><i class="fa-solid fa-download"></i> Export report</button></div><div class="stats-grid"><div class="stat-box"><i class="fa-regular fa-calendar stat-icon"></i><span>Appointments</span><strong>1,248</strong></div><div class="stat-box"><i class="fa-solid fa-users stat-icon"></i><span>Users this month</span><strong>864</strong></div><div class="stat-box"><i class="fa-solid fa-user-tie stat-icon"></i><span>Lawyer registrations</span><strong>54</strong></div><div class="stat-box"><i class="fa-solid fa-wallet stat-icon"></i><span>Revenue</span><strong>'+formatMoney(940000)+'</strong></div></div><div class="dash-grid"><section class="panel"><div class="panel-head"><h3>Appointments per month</h3></div><div class="chart-box"><canvas id="appointmentsChart"></canvas></div></section><section class="panel"><div class="panel-head"><h3>Popular legal services</h3></div><div class="chart-box"><canvas id="serviceChart"></canvas></div></section></div><div class="panel" style="margin-top:20px"><div class="panel-head"><h3>User growth</h3></div><div class="chart-box"><canvas id="usersChart"></canvas></div></div>';}
    function makeChart(id,type,data,options={}){const el=document.getElementById(id);if(!el||typeof Chart==='undefined')return;new Chart(el,{type,data,options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:type==='doughnut',labels:{color:document.body.classList.contains('dark')?'#e9eef9':'#101b31'}}},scales:type==='doughnut'?{}:{x:{grid:{display:false},ticks:{color:'#8493a5'}},y:{grid:{color:'rgba(132,147,165,.16)'},ticks:{color:'#8493a5'}}},...options}});}
    function renderMainChart(){makeChart('mainChart','line',{labels:['Apr','May','Jun','Jul','Aug','Sep'],datasets:[{label:'Appointments',data:[105,135,164,148,207,244],borderColor:'#be8a3b',backgroundColor:'rgba(190,138,59,.12)',fill:true,tension:.35}]});}
    function renderCharts(){makeChart('appointmentsChart','bar',{labels:['Apr','May','Jun','Jul','Aug','Sep'],datasets:[{label:'Appointments',data:[105,135,164,148,207,244],backgroundColor:'#10233e',borderRadius:5}]});makeChart('serviceChart','doughnut',{labels:['Family','Property','Criminal','Corporate','Civil'],datasets:[{data:[29,24,19,16,12],backgroundColor:['#be8a3b','#10233e','#337c72','#8194b0','#d8b477'],borderWidth:0}]});makeChart('usersChart','line',{labels:['Apr','May','Jun','Jul','Aug','Sep'],datasets:[{label:'New users',data:[206,288,321,409,447,528],borderColor:'#168064',backgroundColor:'rgba(22,128,100,.1)',fill:true,tension:.35}]});}
    function renderMessages(){if(!requireLogin())return;const user=getUser(),l=getLawyer(activeConversation)||getLawyer(1),convos=[1,2,4].map(id=>getLawyer(id)).filter(Boolean),messages=(db.get('messages')||[]).filter(m=>m.contact===activeConversation),mine=user.role==='lawyer'?'lawyer':'customer';document.getElementById('conversationList').innerHTML='<h2>Messages</h2>'+convos.map((x,i)=>'<div class="conversation '+(x.id===activeConversation?'active':'')+'" onclick="activeConversation='+x.id+';renderMessages()"><img src="'+x.image+'" alt=""><div class="conversation-main"><strong>'+esc(user.role==='lawyer'&&x.id===1?'Samira Ahmed':x.name)+'</strong><span>'+esc((db.get('messages')||[]).filter(m=>m.contact===x.id).slice(-1)[0]?.text||'Start a conversation')+'</span></div>'+(i===0?'<b class="unread">2</b>':'')+'</div>').join('');document.getElementById('chatName').textContent=user.role==='lawyer'&&l.id===1?'Samira Ahmed':l.name;document.getElementById('messageThread').innerHTML=messages.length?messages.map(m=>'<div class="message '+(m.from===mine?'mine':'')+'">'+esc(m.text)+'<time>'+esc(m.time)+'</time></div>').join(''):emptyState('fa-comment-dots','No messages yet','Start a conversation with this professional.','','');setTimeout(()=>{const t=document.getElementById('messageThread');t.scrollTop=t.scrollHeight;},0);}
    function openMessages(id){if(!requireCustomer())return;activeConversation=Number(id);navigate('messages');}
    function sendMessage(e){e.preventDefault();if(!requireLogin())return;const input=document.getElementById('messageInput'),text=input.value.trim(),user=getUser(),from=user.role==='lawyer'?'lawyer':'customer',replyFrom=from==='lawyer'?'customer':'lawyer';if(!text)return;const messages=db.get('messages')||[];messages.push({id:Date.now(),contact:activeConversation,from,text,time:'Just now'});db.set('messages',messages);input.value='';renderMessages();setTimeout(()=>{const all=db.get('messages')||[];all.push({id:Date.now()+1,contact:activeConversation,from:replyFrom,text:'Thank you for your message. This is an automated demo reply from the Legal Connect workspace.',time:'Just now'});db.set('messages',all);renderMessages();},700);}
    function toggleConversations(){document.getElementById('conversationList').classList.toggle('open');}
    function renderCases(){if(!requireCustomer())return;const cases=db.get('cases')||[];document.getElementById('caseGrid').innerHTML=cases.length?cases.map(c=>'<article class="case-item"><span class="tag">'+esc(c.id)+'</span><h3>'+esc(c.title)+'</h3><p>'+esc(c.category)+' | Created '+esc(c.created)+'</p><div class="case-foot"><span>'+formatStatus(c.status)+'</span><button class="btn ghost small" onclick="showToast(\'Case '+esc(c.id)+' details opened.\')">Open details <i class="fa-solid fa-arrow-right"></i></button></div></article>').join(''):emptyState('fa-folder-open','No cases yet','Open a case to keep your matter organized.','Open a case','createCase()');}
    function createCase(){if(!requireCustomer())return;openModal('case');}
    function saveCase(e){e.preventDefault();const cases=db.get('cases')||[];cases.unshift({id:'LC-C-'+Math.floor(1000+Math.random()*8000),title:document.getElementById('newCaseTitle').value.trim(),lawyerId:1,category:document.getElementById('newCaseCategory').value,created:'Sep 01, 2026',status:'New'});db.set('cases',cases);closeModal();showToast('New case created successfully.');renderCases();}
    function renderDocuments(){if(!requireCustomer())return;const docs=db.get('documents')||[];document.getElementById('documentGrid').innerHTML=docs.length?docs.map(d=>'<article class="document-item"><i class="fa-regular fa-file-lines" style="font-size:26px;color:var(--gold)"></i><h3 style="margin-top:12px">'+esc(d.name)+'</h3><p>Case: '+esc(d.case)+'<br>Uploaded '+esc(d.date)+' | '+esc(d.type)+'</p><div class="document-foot"><span>'+formatStatus(d.status)+'</span><div class="row-actions"><button class="btn outline" onclick="showToast(\'Opening '+esc(d.name)+' in the demo viewer.\')">View</button><button class="btn outline" onclick="showToast(\'Demo download started.\')">Download</button><button class="btn danger" onclick="deleteDocument('+d.id+')">Delete</button></div></div></article>').join(''):emptyState('fa-file-circle-xmark','No documents found','Upload a file to add it to the demo document center.','','');}
    function uploadDocument(e){if(!requireCustomer())return;const f=e.target.files[0];if(!f)return;const allowed=['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','image/jpeg','image/png'];if(!allowed.includes(f.type)){showToast('Choose a PDF, DOC, DOCX, JPG or PNG file.','error');return;}const docs=db.get('documents')||[];docs.unshift({id:Date.now(),name:f.name,case:'Unassigned',date:'Sep 01, 2026',type:f.name.split('.').pop().toUpperCase(),status:'Reviewing'});db.set('documents',docs);e.target.value='';showToast('File upload simulated successfully.');renderDocuments();}
    function deleteDocument(id){openModal('confirm',{title:'Delete document?',message:'This will remove the file from your local demo list.',action:'doDeleteDocument('+id+')',danger:true});}
    function doDeleteDocument(id){db.set('documents',(db.get('documents')||[]).filter(d=>d.id!==Number(id)));showToast('Document deleted.','warn');renderDocuments();}
    function renderAppointments(){if(!requireCustomer())return;const user=getUser(),appts=(db.get('appointments')||[]).filter(a=>a.customer===user.name);document.getElementById('appointmentsTable').innerHTML=appts.length?appts.map(a=>{const l=getLawyer(a.lawyerId);return '<tr><td><div class="table-person"><img src="'+(l?.image||'')+'" alt=""><div><strong>'+esc(l?.name||'Legal professional')+'</strong><span>'+esc(l?.title||'')+'</span></div></div></td><td>'+esc(a.service)+'</td><td>'+esc(a.date)+'<br><span>'+esc(a.time)+'</span></td><td>'+esc(a.type)+'</td><td>'+formatStatus(a.status)+'</td><td><div class="row-actions"><button class="btn outline" onclick="viewProfile('+a.lawyerId+')">View</button>'+(['Pending','Confirmed'].includes(a.status)?'<button class="btn danger" onclick="cancelAppointment(\''+a.id+'\')">Cancel</button>':'')+'</div></td></tr>';}).join(''):'<tr><td colspan="6">'+emptyState('fa-calendar','No appointments yet','Start by finding a lawyer.','Find lawyers','navigate(\'lawyers\')')+'</td></tr>';}
    function filterAppointmentTable(q){document.querySelectorAll('#appointmentsTable tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q.toLowerCase())?'':'none');}
    function cancelAppointment(id){openModal('confirm',{title:'Cancel appointment?',message:'Are you sure you want to cancel this consultation request?',action:"doCancelAppointment('"+id+"')",danger:true});}
    function doCancelAppointment(id){const a=(db.get('appointments')||[]).find(x=>x.id===id);if(a){a.status='Cancelled';db.set('appointments',db.get('appointments'));showToast('Appointment cancelled.','warn');}renderAppointments();}
    function addReview(lawyerId){if(!requireCustomer())return;openModal('review',lawyerId);}
    function saveReview(e,lawyerId){e.preventDefault();const r=db.get('reviews')||[];const lawyer=getLawyer(lawyerId),rating=Number(document.getElementById('reviewRating').value);r.unshift({id:Date.now(),lawyerId,name:getUser().name,rating,text:document.getElementById('reviewText').value.trim(),date:'September 2026'});db.set('reviews',r);lawyer.rating=Number(((lawyer.rating*lawyer.reviews+rating)/(lawyer.reviews+1)).toFixed(1));lawyer.reviews++;db.set('lawyers',getLawyers());closeModal();showToast('Review submitted. Thank you for your feedback.');renderProfile(lawyerId);}
    function renderNotifications(){const notes=db.get('notifications')||[],menu=document.getElementById('notificationMenu');if(!menu)return;const unread=notes.filter(n=>!n.read).length;document.getElementById('notifyDot').style.display=unread?'block':'none';menu.innerHTML='<div class="popover-head"><span>Notifications</span><button class="btn ghost small" onclick="markAllNotifications()">Mark all read</button></div>'+notes.slice(0,8).map(n=>'<div class="notification '+(!n.read?'unread-notification':'')+'" onclick="markNotificationRead('+n.id+')"><p>'+esc(n.text)+'</p><span>'+esc(n.time)+'</span></div>').join('')+(notes.length?'<div class="popover-head"><button class="btn ghost small" onclick="navigate(\'dashboard\');toggleNotifications()">View notification center</button></div>':'');}
    function toggleNotifications(){document.getElementById('notificationMenu').classList.toggle('open');document.getElementById('globalSearch').classList.remove('open');}
    function markNotificationRead(id){const n=db.get('notifications')||[],note=n.find(x=>x.id===Number(id));if(note)note.read=true;db.set('notifications',n);renderNotifications();}
    function markAllNotifications(){const n=db.get('notifications')||[];n.forEach(x=>x.read=true);db.set('notifications',n);renderNotifications();showToast('All notifications marked as read.');}
    function toggleGlobalSearch(){document.getElementById('globalSearch').classList.toggle('open');document.getElementById('notificationMenu').classList.remove('open');if(document.getElementById('globalSearch').classList.contains('open'))document.getElementById('globalSearchInput').focus();}
    function renderGlobalSuggestions(){const q=document.getElementById('globalSearchInput').value.toLowerCase().trim(),out=document.getElementById('globalSuggestions');if(!q){out.innerHTML='';return;}const lawyers=getLawyers().filter(l=>l.name.toLowerCase().includes(q)||l.specialization.join(' ').toLowerCase().includes(q)).slice(0,3),services=getServices().filter(s=>s.name.toLowerCase().includes(q)).slice(0,2);out.innerHTML=[...lawyers.map(l=>'<div class="suggestion" onclick="viewProfile('+l.id+');toggleGlobalSearch()"><i class="fa-solid fa-user-tie"></i> '+esc(l.name)+' <span style="color:var(--muted)">Lawyer</span></div>'),...services.map(s=>'<div class="suggestion" onclick="quickService(\''+esc(s.name)+'\');toggleGlobalSearch()"><i class="fa-solid '+s.icon+'"></i> '+esc(s.name)+' <span style="color:var(--muted)">Service</span></div>')].join('')||'<div class="suggestion">No suggestions found.</div>';}
    function toggleAi(){document.getElementById('aiPanel').classList.toggle('open');}
    function renderResources(){const a=[['Property','Understanding your rights as a tenant','Legal Connect Editorial','Aug 22, 2026'],['Family','Preparing for a first family-law consultation','Legal Connect Editorial','Aug 18, 2026'],['Corporate','A practical guide to reviewing business contracts','Legal Connect Editorial','Aug 10, 2026'],['Criminal','What to prepare before meeting a criminal defence lawyer','Legal Connect Editorial','Aug 05, 2026'],['Civil','How to organize documents for a civil dispute','Legal Connect Editorial','Jul 28, 2026'],['Immigration','Building a checklist for an immigration application','Legal Connect Editorial','Jul 19, 2026']];document.getElementById('resourceGrid').innerHTML=a.map(x=>'<article class="resource-item"><span class="tag">'+x[0]+'</span><h3>'+x[1]+'</h3><p>General educational information to help you prepare questions for a qualified professional.</p><div class="article-foot"><span>'+x[2]+'<br>'+x[3]+'</span><button class="btn ghost small" onclick="showToast(\'This demo article is an educational preview, not legal advice.\',\'warn\')">Read more <i class="fa-solid fa-arrow-right"></i></button></div></article>').join('');}
    function submitContact(e){e.preventDefault();const phone=document.getElementById('contactPhone');if(phone.value&&!/^[+0-9\s-]{7,20}$/.test(phone.value)){showToast('Please enter a valid phone number.','error');phone.focus();return;}e.target.reset();showToast('Your message has been sent to the demo support desk.');}
    function showToast(message,type='success'){const stack=document.getElementById('toastStack'),icon=type==='error'?'fa-circle-xmark':type==='warn'?'fa-triangle-exclamation':'fa-circle-check',toast=document.createElement('div');toast.className='toast '+(type==='success'?'':type);toast.innerHTML='<i class="fa-solid '+icon+'"></i><span>'+esc(message)+'</span>';stack.appendChild(toast);setTimeout(()=>{toast.style.opacity='0';toast.style.transform='translateX(20px)';setTimeout(()=>toast.remove(),250)},3600);}
    window.addEventListener('hashchange',routeFromHash);window.addEventListener('DOMContentLoaded',initApp);
  